def test_service_loop_runs_requests_while_the_fight_loop_waits(qapp):
    """The bug behind "TP to quest says teleporting and nothing happens".

    Requests used to drain at the top of the fight loop, which spends
    nearly all its time blocked inside wait_for_combat -- so a request
    queued while waiting sat there until a fight had started AND
    finished. The service tasks are concurrent, so it acts in about a
    second.

    Both tasks are started because they are what a run starts: the queue
    has its own task and the service tick no longer drains it. Two
    drainers meant both could pop an action, and the second pop
    overwrote `seat.busy` -- so the dedupe stopped covering whichever
    action was actually running.
    """
    import asyncio

    from deimos_bridge.gui.live import LiveWorker

    root, _ = _dialogue_root(visible=False)
    client = _QuestClient(root, in_battle=False)

    worker = LiveWorker(Telemetry(), "ice", [], "school-aware", 1)
    worker.auto_dialogue = False
    worker.seats[0].client = client
    said = []
    worker.status = type("S", (), {"emit": staticmethod(said.append)})()

    async def drive():
        tasks = [asyncio.ensure_future(worker._service_loop(client)),
                 asyncio.ensure_future(worker._request_loop(client))]
        worker.request("teleport")
        # Waits for the REPORT, not for the first teleport. A quest
        # teleport is a retry loop now -- it checks where the wizard
        # landed and tries again -- so the first `client.teleport` is
        # the middle of the action rather than the end of it.
        for _ in range(120):                # ~6s of 50ms ticks
            await asyncio.sleep(0.05)
            if any("teleported" in m for m in said):
                break
        worker._stop = True
        for task in tasks:
            task.cancel()
            try:
                await task
            except BaseException:
                pass

    asyncio.run(drive())
    assert client.teleported, "the request never ran"
    assert any("teleported" in m for m in said)


def test_service_loop_leaves_the_mouse_alone_during_combat(qapp):
    """Two coroutines clicking at once produce misclicks, so anything
    that clicks is skipped while a duel is on."""
    import asyncio

    from deimos_bridge.gui.live import LiveWorker

    root, button = _dialogue_root(visible=True)
    client = _QuestClient(root, in_battle=True)

    worker = LiveWorker(Telemetry(), "ice", [], "school-aware", 1,
                        auto_dialogue=True)
    worker.status = type("S", (), {"emit": staticmethod(lambda *_: None)})()

    async def drive():
        task = asyncio.ensure_future(worker._service_loop(client))
        worker.request("teleport")
        await asyncio.sleep(0.3)
        worker._stop = True
        task.cancel()
        try:
            await task
        except BaseException:
            pass

    asyncio.run(drive())
    assert client.teleported == []
    assert client.mouse_handler.clicks == []


def _party_worker(goals=("a", "b"), ahead_at=(10.0, 5.0)):
    """A two-seat worker with each wizard's goal and when it last moved."""
    from deimos_bridge.gui.live import LiveWorker, SeatConfig

    worker = LiveWorker(Telemetry(), "ice", [], "school-aware", 1,
                        seats=[SeatConfig(school="fire", deck=[],
                                          policy_name="school-aware")])
    worker.status = type("S", (), {"emit": staticmethod(lambda *_: None)})()
    worker.DESYNC_GRACE = 0.0
    for seat, goal, at in zip(worker.seats, goals, ahead_at):
        seat.goal, seat.goal_at = goal, at
        seat.client = object()
    return worker


def _lose_a_fight(worker, seat, opening, rounds=20, seats_in_plan=1):
    """Play a losing duel into this seat's telemetry, then end it."""
    from deimos_bridge.telemetry import RoundRecord

    seat.tel.start_fight()
    index = seat.tel.fights[-1].index
    for i in range(rounds):
        seat.tel.rounds.append(RoundRecord(
            fight=index, round=i + 1, passing=False,
            seats_in_plan=seats_in_plan))
    seat.tel.fights[-1].opening = opening
    seat.tel.fights[-1].rounds = rounds
    seat.tel.end_fight(False)
    worker._note_the_loss(seat, False)


def _no_line_round(worker, seat, hp=1998.0, died=True, n=4, seats_in_plan=1,
                   hand=(), hidden=()):
    """One round whose candidate set either all died or did not, pushed
    through the same path `_on_decision` uses.

    The hand defaults to EMPTY, which since the deck-out rule means a
    wizard that has run out of cards — the one state the run leaves a
    duel for. Tests that want the ordinary case, a wizard with a board
    to play, pass one. See `LiveWorker._still_holding_cards`.
    """
    import time

    from deimos_bridge.telemetry import RoundRecord

    fight = seat.tel.fights[-1].index if seat.tel.fights else 1
    # 14 turns at a horizon of 12 is `died()`; 6 turns is a real count.
    cands = [{"card": f"c{i}", "turns": 14 if died else 6, "horizon": 12}
             for i in range(n)]
    rec = RoundRecord(fight=fight, round=len(seat.tel.rounds) + 1,
                      candidates=cands, player_hp=hp, player_max_hp=1998.0,
                      seats_in_plan=seats_in_plan,
                      hand=list(hand), hidden=list(hidden))
    seat.tel.rounds.append(rec)
    # What `_on_decision` stamps, so a partner reading this seat's hand
    # sees what the round saw.
    seat.hand_seen = (len(rec.hand) + len(rec.hidden), time.monotonic())
    worker._watch_for_a_fight_that_cannot_be_won(seat, rec)
    return rec


def test_a_fight_with_no_surviving_line_is_said_out_loud(qapp):
    """The verdict already existed and already went in the export. A
    rollout that dies returns `_lost_score`'s sentinel instead of a turn
    count, `policies.is_sentinel` classifies it, and its only caller in
    the repo is a pip-thrift tie-break inside the ranking — so the one
    component that knew the fight was unwinnable told nobody.

    Rev 8ebfcf70's fight 2 opened with SEVEN rounds in a row where every
    candidate, `pass` included, was that sentinel, at 1998 of 1998
    health. 19 of its 26 rounds read that way, the board was walked back
    into twice more, and nothing said a word until the wizard was dead
    three times over."""
    worker = _party_worker()
    seat, other = worker.seats
    seat.tel.start_fight()
    seat.tel.fights[-1].opening = "Drusilla Morningbane@2400+War Wyrm@685"
    for _ in range(worker.UNWINNABLE_ROUNDS - 1):
        _no_line_round(worker, seat)
    assert not [e for e in seat.tel.questing if e["kind"] == "unwinnable"], \
        "a handful of bad hands is not a verdict"
    _no_line_round(worker, seat)
    said = [e for e in seat.tel.questing if e["kind"] == "unwinnable"]
    assert len(said) == 1, [e["kind"] for e in seat.tel.questing]
    assert "Drusilla Morningbane@2400" in said[0]["detail"]
    assert "planning them alone" in said[0]["detail"]
    assert "1998 of 1998 health" in said[0]["detail"], \
        "the verdict arrived at full health and the line did not say so"
    assert [e for e in other.tel.questing if e["kind"] == "unwinnable"]


def test_one_line_that_survives_clears_the_count(qapp):
    """Consecutive, not cumulative. A fight that has an answer on some
    rounds and not others is a hard fight, not a wall."""
    worker = _party_worker()
    seat = worker.seats[0]
    seat.tel.start_fight()
    for _ in range(worker.UNWINNABLE_ROUNDS - 1):
        _no_line_round(worker, seat)
    _no_line_round(worker, seat, died=False)
    assert seat.no_line_survives == 0
    for _ in range(worker.UNWINNABLE_ROUNDS - 1):
        _no_line_round(worker, seat)
    assert not [e for e in seat.tel.questing if e["kind"] == "unwinnable"]


def test_a_round_with_nothing_to_roll_out_neither_counts_nor_clears(qapp):
    """An empty candidate set is a round with nothing castable, not a
    round where no line survives. Counting it would invent verdicts out
    of a dry hand; clearing on it would hide a real one."""
