    was = seat.no_line_survives
    empty = RoundRecord(fight=1, round=99, candidates=[],
                        player_hp=100.0, player_max_hp=1998.0)
    worker._watch_for_a_fight_that_cannot_be_won(seat, empty)
    assert seat.no_line_survives == was


