    hm.set_matrix([("r1", {"a": (3.0, True, "note")})], ["a"])
    hm.grab()
    assert "chosen" in hm.hit_text(0)

    rb = RankedBars("t")
    rb.resize(360, 200)
    rb.grab()
    rb.set_bars([("a", 2.0, True, "note")])
    rb.grab()

    m = Meter("cover")
    m.resize(300, 74)
    m.set_value(0.5, "3 of 6", "good")
    m.grab()


