    w = LiveWorker(Telemetry(), "ice", [], "school-aware", 1)
    w.status = type("S", (), {"emit": staticmethod(said.append)})()
    seat = w.seats[0]

    class _Runner:
        running = True
        stale = False
        failures = 0
        steps = 0
        last_error = "RuntimeError: no such window"

