    worker, seat, boss = _stranded_in_a_dungeon(monkeypatch,
                                                crosses_on_leg=None)
    asyncio.run(worker._follow_step(seat.client, seat))
    assert len(seat.client.tped) == 1, "the first walk did not happen"
