# ---------------- a placement that cannot settle must not pause the party
#
# Rev cfeb9a85's last seven minutes: six catch-ups, three of them ended
# within fourteen seconds of starting — 4025.7, 4049.8, 4063.4 — each
# naming a DIFFERENT wizard as the one behind (Phönix 13 quests, then
# Sebastian 11, then both 11). The party was genuinely spread across
# mainline and Arena side content, so "who is behind" had no stable
# answer, and every restart paused the script again.

def _churning(worker):
    """Drive the "a different wizard is behind" branch once."""
    import time

    laggard = worker.seats[0]
    now = time.monotonic()
    worker._catch_up_state = {
        "seats": [laggard], "gap": 1, "started": now, "moved": now,
        "goals": {id(laggard): laggard.goal}, "why": "",
    }
    for seat in worker.seats:
        seat.progress = ("KT_ChampHall", (1, 2, 3), seat.goal)
        seat.progress_at = now
        seat.in_duel = False
    # somebody ELSE is the one behind now
    worker.seats[1].quest_name = "Give em Another Round"
    worker.seats[0].quest_name = "Back to Winthrop"
    worker._check_caught_up()


def test_three_changes_of_mind_stop_the_catch_ups():
    import time

    worker = _behind_party()
    for _ in range(3):
        _churning(worker)
        worker.seats[1].quest_name, worker.seats[0].quest_name = (
            worker.seats[0].quest_name, worker.seats[1].quest_name)
    assert worker._churn >= worker.CATCH_UP_CHURN, worker._churn

    worker._catch_up_state = None
    worker._start_catching_up([worker.seats[0]], 1, "questline")
    assert worker._catch_up_state is None, \
        "it paused the party again for a reading that keeps changing"
    note = [e for e in worker.seats[0].tel.questing
            if e["kind"] == "catch-up-churn"]
    assert note and "DIFFERENT wizard" in note[0]["detail"]


def test_the_rest_expires_and_catch_ups_resume():
    import time

    worker = _behind_party()
    worker._churn = worker.CATCH_UP_CHURN
    worker._churn_at = time.monotonic() - worker.CATCH_UP_CHURN_REST - 1
    worker._start_catching_up([worker.seats[0]], 1, "questline")
    assert worker._catch_up_state is not None, "the rest never ended"


def test_a_catch_up_that_finished_clears_the_churn():
    """One real rescue is evidence the placement CAN settle."""
    import time

    worker = _behind_party()
    worker._churn = 5
    # everybody on the same quest -> nobody behind -> "done"
    for seat in worker.seats:
        seat.quest_name = "Back to Winthrop"
        seat.goal = "goal for Back to Winthrop"
    now = time.monotonic()
    worker._catch_up_state = {
        "seats": [worker.seats[0]], "gap": 1, "started": now, "moved": now,
        "goals": {}, "why": "",
    }
    worker._check_caught_up()
    assert worker._churn == 0
    assert worker._catch_up_state is None


def test_one_change_of_mind_is_not_churn():
    worker = _behind_party()
    _churning(worker)
    assert worker._churn == 1
    worker._catch_up_state = None
    worker._start_catching_up([worker.seats[0]], 1, "questline")
    assert worker._catch_up_state is not None, \
        "a single retarget must still be allowed to start again"


def test_every_await_in_the_service_tick_is_bounded():
    """The loop's own body is where a hung client kills a seat silently:
    a stage has a deadline, a bare await does not, and the heartbeat
    that would show the seat had gone quiet is written at the TOP of the
    tick — so a read that never returns stops the heartbeats too.

    Rev f32be436 lost the party's script to the combat read. Rev
    35f0fc6e lost Konstantin's tick at t=4230 to the goal read, with no
    `client-not-answering` against it because that guard only covers the
    combat one. Both were the last bare await of their day."""
    import inspect
    import re

    from deimos_bridge.gui.live import LiveWorker

    src = inspect.getsource(LiveWorker._service_loop)
    body = src.split('"""', 2)[2]
    bare = []
    for line in body.splitlines():
        stripped = line.strip()
        if not stripped.startswith("await "):
            continue
        if re.match(r"await self\._stage\(", stripped):
            continue
        # The bounded reads and the loop's own sleep are fine.
        if re.match(r"await (asyncio\.sleep|self\._read_in_battle|"
                    r"self\._heartbeat)\(", stripped):
            continue
        bare.append(stripped)
    assert not bare, (
        "a bare await in the service tick — a client that stops "
        f"answering it takes this seat off the air with no timeout, no "
        f"exception and no heartbeat: {bare}")


# ------------- a stage cut off waiting for the wheel never ran at all
# Rev f2b8101f printed this to the console, next to `stage-timeout:
# unwedging a stuck script cut off after 90s`:
#
#     RuntimeWarning: coroutine 'LiveWorker._unstick' was never awaited
#
# One event, described two wrong ways. `_unstick` did not run for 90
# seconds; it waited 90 seconds for a drive lock somebody else held, was
# cancelled before `_at_the_wheel` ever reached `await coro`, and its
# coroutine was then garbage-collected un-started.

def _wheel_held(worker, seat, holding):
    """Hold this seat's drive lock so nothing else can take it.

    `holding` is set once the lock is actually held — waiting a tick is
    not enough, and a test that races the holder proves nothing.
    """
    import asyncio

    async def hog():
        async with worker._driving(seat, "something slow"):
            holding.set()
            await asyncio.Event().wait()

    return hog


def test_a_stage_that_never_got_the_wheel_says_so(qapp):
    import asyncio

    worker, _read = _zoned_party(["KT_Hub"])
    seat = worker.seats[0]
    ran = []

    async def work():
        ran.append(True)

    async def go():
        # A real lock, made inside the running loop. Without one
        # `_driving` is a nullcontext and every stage gets the wheel at
        # once, which is not the situation being tested.
        seat.drive = asyncio.Lock()
        holding = asyncio.Event()
        holder = asyncio.create_task(_wheel_held(worker, seat, holding)())
        await holding.wait()
        try:
            await worker._stage(seat, "unwedging a stuck script", work(),
                                limit=0.2, wheel=True)
        finally:
            holder.cancel()

    asyncio.run(go())
    assert ran == [], "it got the wheel after all — the test proves nothing"
    said = [e for e in seat.tel.questing if e["kind"] == "stage-timeout"]
    assert said, [e["kind"] for e in seat.tel.questing]
    assert "never started" in said[0]["detail"], said[0]["detail"]
    assert "cut off after" not in said[0]["detail"], \
        "a stage that never ran is still reported as one that ran too long"


def test_a_dropped_stage_closes_the_coroutine_it_never_ran(qapp):
    """The RuntimeWarning itself, asserted on the mechanism rather than
    on the warning: Python only emits it when the un-started coroutine
    is garbage-collected, and pytest intercepts that as an unraisable
    rather than something a test can catch. A closed coroutine has no
    frame, and closing it is exactly what stops the warning."""
    import asyncio

    worker, _read = _zoned_party(["KT_Hub"])
    seat = worker.seats[0]

    async def work():
        return None

    work_coro = work()

    async def go():
        seat.drive = asyncio.Lock()
        holding = asyncio.Event()
        holder = asyncio.create_task(_wheel_held(worker, seat, holding)())
        await holding.wait()
        try:
            await worker._stage(seat, "unwedging a stuck script", work_coro,
                                limit=0.2, wheel=True)
        finally:
            holder.cancel()

    asyncio.run(go())
    assert work_coro.cr_frame is None, \
        ("the stage's coroutine was left un-started for the garbage "
         "collector to warn about")


def test_a_stage_that_ran_and_overran_is_still_reported_as_that(qapp):
    """The other half: a stage that DID get the wheel and then took too
    long is the original message, and it should not have been changed."""
    import asyncio

    worker, _read = _zoned_party(["KT_Hub"])
    seat = worker.seats[0]

    async def slow():
        await asyncio.Event().wait()

    asyncio.run(worker._stage(seat, "auto-dialogue", slow(),
                              limit=0.2, wheel=True))
    said = [e for e in seat.tel.questing if e["kind"] == "stage-timeout"]
    assert said and "cut off after" in said[0]["detail"], said


def test_a_dialogue_does_not_burn_the_name_resolvers_cooldown(monkeypatch):
    """A refusal is not an attempt — the rule `_maybe_rearm_quest_arrow`
    follows and this rung broke.

    Rev f2b8101f: the party spent that run in a dungeon and was out of
    combat for about ten seconds in sixteen minutes. Every tick that
    reached this rung found a dialogue open, spent the two-minute
    cooldown and returned, so eight attempts in a row read nothing and
    the account settings stayed at their placeholder for the whole run.
    """
    import asyncio

    from deimos_bridge import party, questing

    worker, asked = _resolving(monkeypatch, [
        _friends_text("Sebastian Life", "Konstantin Ice"),
        _friends_text("Phönix Storm"),
        "",
    ])
    talking = [True]

    async def in_dialogue(_c):
        return talking[0]

    monkeypatch.setattr(questing, "in_dialogue", in_dialogue)
    for _ in range(4):
        asyncio.run(worker._resolve_party_names(worker.seats[0]))
    assert asked == []
    # ...and the moment the box clears, it reads — without waiting out a
    # cooldown it never should have spent.
    talking[0] = False
    asyncio.run(worker._resolve_party_names(worker.seats[0]))
    assert asked, "the cooldown was spent on ticks that never looked"
    assert 'var Main_Account = "Phönix Storm"' in worker.script
    party._FULL_NAMES.clear()


def test_a_party_all_in_duels_does_not_burn_the_cooldown_either(monkeypatch):
    """The friends list cannot be opened from inside a duel, so a party
    mid-fight is another refusal rather than a failed attempt."""
    import asyncio

    from deimos_bridge import party

    worker, asked = _resolving(monkeypatch, [
        _friends_text("Sebastian Life", "Konstantin Ice"),
        _friends_text("Phönix Storm"),
        "",
    ])
    for seat in worker.seats:
        seat.in_duel = True
    asyncio.run(worker._resolve_party_names(worker.seats[0]))
    assert asked == []
    for seat in worker.seats:
        seat.in_duel = False
    asyncio.run(worker._resolve_party_names(worker.seats[0]))
    assert asked, "a fight that ended still had to wait out a cooldown"
    party._FULL_NAMES.clear()


# --------------- the script's dialogue clearer that never clears anything
# The operator, and it is two symptoms of one cause: "the auto dialogue
# works but when scripting is enabled I suppose it uses the quest script
# dialogue functions but it waits a long time to start the dialogue / go
# through it".
#
# It does not use them. Every preset's general handler is
#
#     if any hasdialogue {
#         print "Dialogue detected. Clearing..."
#         if Handle_Dialogue = True { sameany sendkey SPACEBAR, .1 }
#     }
#
# and `Handle_Dialogue` is declared nowhere in 14,427 lines. deimoslang
# reads an undefined constant as False without complaining, so the box is
# announced and never touched — while wizAi, whose clicker works, stood
# back for a handler that does not run.

_DEAD_GUARD = ('###deimos_expertmode\n'
               'var DebugMode = True\n'
               'block Any_Dialogue {\n'
               '  if any hasdialogue {\n'
               '    if Handle_Dialogue = True {\n'
               '      sameany sendkey SPACEBAR, .1\n'
               '    }\n'
               '  }\n'
               '}\n')


def test_an_undeclared_guard_on_the_dialogue_key_is_found():
    from deimos_bridge import scripts

    assert scripts.dead_dialogue_guard(_DEAD_GUARD) == "Handle_Dialogue"


def test_a_script_that_declares_the_guard_keeps_its_own_dialogue():
    from deimos_bridge import scripts

    alive = _DEAD_GUARD.replace("var DebugMode = True\n",
                                "var DebugMode = True\n"
                                "var Handle_Dialogue = True\n")
    assert scripts.dead_dialogue_guard(alive) == ""


def test_an_unguarded_key_press_is_a_working_handler():
    from deimos_bridge import scripts

    assert scripts.dead_dialogue_guard(
        "block B {\n  sameany sendkey SPACEBAR, .1\n}\n") == ""


def test_a_per_quest_key_press_is_not_the_general_handler():
    """The presets press space in quest sequences and in the spell
    trainer, and those are not the handler this is about. The question
    is narrow on purpose: is a dialogue press gated on a name that can
    never be true."""
    from deimos_bridge import scripts

    both = _DEAD_GUARD + ('block Spell_Learner {\n'
                          '  if any hasdialogue {\n'
                          '    sameany sendkey SPACEBAR, .1\n'
                          '  }\n'
                          '}\n')
    assert scripts.dead_dialogue_guard(both) == "Handle_Dialogue"


def test_every_shipped_preset_has_its_dialogue_clearer_switched_off():
    """Not a lint that might fire — a fact about all six, and the reason
    wizAi now clicks their dialogue. If a preset is ever fixed upstream
    this fails, and the right answer then is to let it handle its own."""
    from deimos_bridge import scripts

    presets = scripts.presets()
    assert presets, "no presets shipped"
    for title, path in presets:
        source = scripts.read_preset(path)
        assert scripts.dead_dialogue_guard(source) == "Handle_Dialogue", title


def test_the_dead_dialogue_guard_is_declared_rather_than_left_dead():
    """Reporting it was not enough. Rev b37ab0a2 printed "Dialogue
    detected. Clearing..." **90 times** while pressing nothing, and
    Thomas spent 79 of that run's 136 minutes — 58% — on one line,
    `Talk To Arena Master in Grand Arena`.

    The declaration is added rather than the guard rewritten: the
    author's press is already on the line, and one missing `var` is the
    whole reason deimoslang answers it False."""
    from deimos_bridge import scripts

    out, name = scripts.wake_dialogue(_DEAD_GUARD)
    assert name == "Handle_Dialogue"
    assert "var Handle_Dialogue = True" in out
    assert scripts.dead_dialogue_guard(out) == ""
    # ...and the press itself is untouched.
    assert "sameany sendkey SPACEBAR, .1" in out


def test_the_declaration_lands_before_the_first_block():
    """A deimoslang `var` is a top-level statement. Put after the first
    `block` it would be as dead as the guard it is fixing."""
    from deimos_bridge import scripts

    out, _name = scripts.wake_dialogue(_DEAD_GUARD)
    lines = out.splitlines()
    decl = next(i for i, l in enumerate(lines)
                if l.startswith("var Handle_Dialogue"))
    block = next(i for i, l in enumerate(lines) if l.startswith("block "))
    assert decl < block


def test_waking_a_script_twice_changes_nothing_the_second_time():
    """Idempotent by construction — once the name is declared,
    `dead_dialogue_guard` returns "" and there is nothing to do. The VM
    is rebuilt on every reload and a rewrite that stacked would grow the
    file each time."""
    from deimos_bridge import scripts

    once, _n = scripts.wake_dialogue(_DEAD_GUARD)
    twice, name = scripts.wake_dialogue(once)
    assert twice == once and name == ""


def test_every_shipped_preset_can_be_woken():
    """The companion to
    `test_every_shipped_preset_has_its_dialogue_clearer_switched_off`:
    all six are broken the same way and all six take the same repair,
    line endings and all."""
    from deimos_bridge import scripts

    presets = scripts.presets()
    assert presets, "no presets shipped"
    for title, path in presets:
        source = scripts.read_preset(path)
        out, name = scripts.wake_dialogue(source)
        assert name == "Handle_Dialogue", title
        assert scripts.dead_dialogue_guard(out) == "", title
        # The shipped presets are CRLF. A lone LF inserted into one is a
        # line deimoslang's parser sees differently from its neighbours.
        if "\r\n" in source:
            assert "var Handle_Dialogue = True\r\n" in out, title


def test_undeclared_guards_are_reported_generally():
    """`Handle_Dialogue` is not the only one — the presets also guard on
    `Delay_Combat`, declared nowhere either. A guard on a name that
    cannot be true is a feature that is silently off."""
    from deimos_bridge import scripts

    names = {n for n, _line in scripts.undeclared_guards(_DEAD_GUARD)}
    assert names == {"Handle_Dialogue"}
    presets = scripts.presets()
    if presets:
        found = {n for n, _l in
                 scripts.undeclared_guards(scripts.read_preset(presets[0][1]))}
        assert "Handle_Dialogue" in found and "Delay_Combat" in found, found


def test_wizai_takes_dialogue_for_a_script_that_cannot_clear_it(qapp):
    worker, _read = _zoned_party(["KT_Hub"] * 2)
    worker.script = _DEAD_GUARD
    assert worker._dialogue_is_ours() is True
    said = [e for e in worker.seats[0].tel.questing
            if e["kind"] == "script-dialogue-dead"]
    assert said and "Handle_Dialogue" in said[0]["detail"]
    # ...said once, not re-derived every tick.
    for _ in range(5):
        worker._dialogue_is_ours()
    assert len([e for e in worker.seats[0].tel.questing
                if e["kind"] == "script-dialogue-dead"]) == 1


def test_wizai_stays_out_of_a_script_that_does_clear_dialogue(qapp):
    worker, _read = _zoned_party(["KT_Hub"] * 2)
    worker.script = _DEAD_GUARD.replace(
        "var DebugMode = True\n",
        "var DebugMode = True\nvar Handle_Dialogue = True\n")
    assert worker._dialogue_is_ours() is False
    assert not [e for e in worker.seats[0].tel.questing
                if e["kind"] == "script-dialogue-dead"]


def test_a_rewritten_script_is_re_examined(qapp):
    """`configure` and the debug toggle rewrite the source mid-run, and
    a reload can swap the script entirely."""
    worker, _read = _zoned_party(["KT_Hub"] * 2)
    worker.script = _DEAD_GUARD
    assert worker._dialogue_is_ours() is True
    worker.script = _DEAD_GUARD.replace(
        "var DebugMode = True\n",
        "var DebugMode = True\nvar Handle_Dialogue = True\n")
    assert worker._dialogue_is_ours() is False


def test_the_auto_dialogue_gate_asks_whose_dialogue_it_is():
    import inspect

    from deimos_bridge.gui.live import LiveWorker

    src = inspect.getsource(LiveWorker._service_loop)
    assert "not driven or self._dialogue_is_ours()" in src, \
        "wizAi stands back from every scripted wizard's dialogue again"


def test_toggling_the_script_log_mid_run_rebuilds_the_script(qapp,
                                                            monkeypatch):
    """`set_debug` is baked into the build, so a runner built with the
    flag off keeps `DebugMode = False` whatever the checkbox says now.
    The 115-minute run at rev f2b8101f: "Script log" ticked mid-run, the
    capture attached instantly, and nothing printed — the export's
    script log only starts at t=1054 because the name fill happened to
    rebuild the script 44 seconds later. Without that coincidence it
    stays empty for the rest of the run."""
    import asyncio

    worker, _read = _zoned_party(["KT_Hub"])
    seat = worker.seats[0]
    worker.script = _QUESTER
    worker.script_debug = False
    built = []

    async def setup(_client, s):
        built.append(worker.script_debug)
        runner = _LiveRunner()
        runner.stop = lambda: None
        s.runner = runner

    monkeypatch.setattr(worker, "_setup_script", setup)
    monkeypatch.setattr(worker, "_scripted", lambda s: True)
    asyncio.run(worker._sync_script(seat))
    assert built == [False]
    # Same text, same flag: no rebuild.
    asyncio.run(worker._sync_script(seat))
    assert built == [False]
    # The operator ticks "Script log": same text, different flag — the
    # runner must be rebuilt so its DebugMode follows.
    worker.script_debug = True
    asyncio.run(worker._sync_script(seat))
    assert built == [False, True], \
        "ticking Script log mid-run did not rebuild — DebugMode stays off"


# ----------------------- the journal's Quest Finder pseudo-entry
# Rev f2b8101f, the last 25 minutes: Sebastian's tracked quest read
# "quest finder" — the journal tab the script's own lost-quest routine
# leaves selected when a cycle fails partway. No quest tracked at all.
# Every rung looked past him, each for a locally-correct reason: the
# off-questline check skips unknown names (unreadable must not be called
# a side quest), the recovery rung required a KNOWN placement, and the
# marker read stale coordinates from the last real quest so the rearm
# never saw a dead hook. "Quest Finder" is not unreadable — it is the
# journal affirmatively saying nothing is selected.

def test_the_quest_finder_pseudo_entry_is_recognised():
    from deimos_bridge import questlist

    assert questlist.no_quest_selected("Quest Finder")
    assert questlist.no_quest_selected("quest finder")
    assert not questlist.no_quest_selected("Eye of Krok")
    assert not questlist.no_quest_selected("")
    assert not questlist.no_quest_selected(None)


def test_a_journal_on_quest_finder_is_reported_as_nothing_selected():
    import time

    from deimos_bridge import questlist

    worker = _party_on_quests(["Gather the Troops", "Gather the Troops",
                               "Quest Finder"])
    finder = questlist.position_of("Quest Finder")
    assert not finder.known, "the precondition of the whole bug"
    worker._places = lambda: [questlist.position_of("Gather the Troops"),
                              questlist.position_of("Gather the Troops"),
                              finder]
    worker._check_on_questline()                    # starts the clock
    assert worker.seats[2].off_line_since is not None, \
        "the pseudo-entry was skipped as an unreadable tracker again"
    worker.seats[2].off_line_since = time.monotonic() - 300
    worker._check_on_questline()
    said = [e for e in worker.seats[0].tel.questing
            if e["kind"] == "off-questline"]
    assert said, "nothing owns the no-quest-selected state"
    assert "NO quest selected" in said[0]["detail"]
    assert "Quest Finder pseudo-entry" in said[0]["detail"]
    assert "side quest" not in said[0]["detail"], \
        "the pseudo-entry is not a side quest and must not be called one"


def test_a_genuinely_unreadable_tracker_is_still_skipped():
    """The rule the pseudo-entry is an exception TO must survive it."""
    from deimos_bridge import questlist

    worker = _party_on_quests(["Gather the Troops", "Gather the Troops"])
    worker._places = lambda: [questlist.position_of("Gather the Troops"),
                              questlist.Position()]          # nothing read
    worker._check_on_questline()
    worker._check_on_questline()
    assert worker.seats[1].off_line_since is None


def test_the_recovery_selects_a_real_quest_for_a_quest_finder_journal(
        monkeypatch):
    """The cure, end to end: the pseudo-entry passes the recovery gate,
    `_lost_quest` names where the party is, and the book click puts a
    real quest back on the tracker."""
    import asyncio
    import time

    from deimos_bridge import questlist

    questing = _no_dialogue(monkeypatch)
    worker = _party_on_quests(["Gather the Troops", "Gather the Troops",
                               "Quest Finder"])
    lost = worker.seats[2]
    places = [questlist.position_of("Gather the Troops"),
              questlist.position_of("Gather the Troops"),
              questlist.position_of("Quest Finder")]
    worker._places = lambda: list(places)
    lost.off_line_since = time.monotonic() - 400
    calls = []

    async def select(_c, names, on_status=None):
        calls.append(list(names))
        return True, names[0], True

    monkeypatch.setattr(questing, "select_quest", select)
    asyncio.run(worker._maybe_recover_questline(lost))
    assert calls == [["Gather the Troops"]], \
        "the pseudo-entry still cannot reach the recovery"
    said = [e for e in lost.tel.questing
            if e["kind"] == "questline-recovered"]
    assert said and "'Quest Finder'" in said[0]["detail"]


def test_the_recovery_reaches_a_quest_the_book_has_never_heard_of(
        monkeypatch):
    """The cure that was sitting behind the gate for 152 minutes.

    `_maybe_recover_questline`'s own docstring says selection is the
    whole cure — "the moment the right quest is tracked, the marker
    points at the main line again and every mover already in the ladder
    aims correctly without being told". Rev ebc4aff8 never reached it:
    the side quest was missing from the data, so `place.known` was
    False, and both this rung's gate and `_check_on_questline` read
    that as "no evidence".

    `seat.last_main` had already recorded the answer at t=1995 —
    Zafaria main #149, 'Heart of Darkness' — and nothing used it."""
    import asyncio
    import time

    from deimos_bridge import questlist

    questing = _no_dialogue(monkeypatch)
    worker = _party_on_quests(["Heart of Darkness", "you can dig it"],
                              ["Talk To Someone in Baobab Crown",
                               "Collect Dirt Mound in Cyclops Lane"])
    lost = worker.seats[1]
    worker._places = lambda: [questlist.position_of("Heart of Darkness"),
                              questlist.position_of("you can dig it")]
    lost.last_main = ("Zafaria", 149, "Heart of Darkness")
    lost.off_line_since = time.monotonic() - 400
    calls = []

    async def select(_c, names, on_status=None):
        calls.append(list(names))
        return True, names[0], True

    monkeypatch.setattr(questing, "select_quest", select)
    asyncio.run(worker._maybe_recover_questline(lost))
    assert calls, "an unlistable quest still cannot reach the recovery"
    assert "Heart of Darkness" in calls[0], \
        f"it selected {calls[0]} rather than the line the party is on"


# ---------------------------------------------------- archmastery school pips
def test_archmastery_school_pips_are_read_into_the_actor():
    """A max-level wizard's rack converts to SCHOOL pips — neither
    normal nor power — and a read that ignored them priced the storm
    booster Oz at 0 pips for 22 straight rounds of passing while the
    game showed every card in his hand castable. Own-school pips land
    in the sim's `school_pips` (worth 2 there and nothing elsewhere —
    the archmastery lock `Ruleset.afford` already models); pips of any
    other school spend like white pips, so they fold into norm_pips."""
    import asyncio

    from data_full import load_spells_full
    from deimos_bridge.live_state import NameResolver, read_state
    from deimos_bridge.mock_client import MockCard, MockCombat, MockMember

    cards = load_spells_full()
    me = MockMember("Oz", 10008, client=True, normal_pips=0, power_pips=0,
                    school_pips={"storm": 3, "balance": 1})
    mob = MockMember("Grave Phantom", 625, monster=True)
    combat = MockCombat([me, mob], [MockCard("Stormblade")])
    read = asyncio.new_event_loop().run_until_complete(
        read_state(combat, NameResolver(cards), "storm"))
    p = read.state.player
    assert (p.school_pips, p.norm_pips, p.pow_pips) == (3, 1, 0)


def test_a_member_without_an_archmastery_rack_reads_as_before():
    """Mocks and older builds have no `school_pips` accessor, and that
    absence must cost nothing — the two familiar counters carry on."""
    import asyncio

    from data_full import load_spells_full
    from deimos_bridge.live_state import NameResolver, read_state
    from deimos_bridge.mock_client import MockCard, MockCombat, MockMember

    cards = load_spells_full()
    me = MockMember("W", 800, client=True, normal_pips=2, power_pips=1)
    mob = MockMember("m", 180, monster=True)
    combat = MockCombat([me, mob], [MockCard("Fireblade")])
    read = asyncio.new_event_loop().run_until_complete(
        read_state(combat, NameResolver(cards), "fire"))
    p = read.state.player
    assert (p.school_pips, p.norm_pips, p.pow_pips) == (0, 2, 1)


def test_an_enemys_rack_folds_by_its_own_school():
    """The rack is read for everyone on the board, and "own school"
    means the ACTOR's school, not the client's: a fire mob's fire pips
    are its power currency, and its stray storm pip spends like a white
    pip. The enemy rack matters for the same reason enemy pips were
    un-zeroed here in the first place — "the boss has six pips" decides
    whether to shield this round or next."""
    import asyncio

    from data_full import load_spells_full
    from deimos_bridge.deimos_damage import school_id
    from deimos_bridge.live_state import NameResolver, read_state
    from deimos_bridge.mock_client import MockCard, MockCombat, MockMember

    cards = load_spells_full()
    me = MockMember("W", 800, client=True, normal_pips=1)
    mob = MockMember("Firebrand", 500, monster=True,
                     school_id=school_id("fire"), normal_pips=1,
                     school_pips={"fire": 2, "storm": 1})
    combat = MockCombat([me, mob], [MockCard("Fireblade")])
    read = asyncio.new_event_loop().run_until_complete(
        read_state(combat, NameResolver(cards), "ice"))
    e = read.state.enemies[0]
    assert (e.school_pips, e.norm_pips) == (2, 2)


def test_a_round_record_carries_the_archmastery_rack():
    """The 22-round pass-fest was only diagnosable because the round
    records showed the pips the POLICY believed. The rack it was blind
    to has to be in the same place, or the next blindness is invisible
    again."""
    tel = Telemetry()
    read = _read(2000, 1, hand=("Fireblade",))
    read.state.player.school_pips = 3
    tel.observe(_Decision("Fireblade"), read)
    assert tel.rounds[-1].school_pips == 3


# ------------------------------------------------------------- booster party
def test_a_booster_party_makes_every_non_leader_a_booster(qapp):
    """The leader is the QUESTER — the one wizard whose questline the
    run levels — and everyone else is muscle for its fights. Following
    is the mode, not the checkbox: a booster that does not chase the
    quester boosts nothing."""
    from deimos_bridge.gui.live import LiveWorker, SeatConfig

    w = LiveWorker(Telemetry(), "ice", [], "ttk-lookahead", 1,
                   seats=[SeatConfig(school="fire"),
                          SeatConfig(school="storm")],
                   booster_party=True, leader=1)
    assert [w._is_booster(s) for s in w.seats] == [True, False, True]
    w.follow_leader = False
    assert [w._follows(s) for s in w.seats] == [True, False, True]


def test_without_the_mode_or_alone_nobody_boosts(qapp):
    from deimos_bridge.gui.live import LiveWorker, SeatConfig

    plain = LiveWorker(Telemetry(), "ice", [], "ttk-lookahead", 1,
                       seats=[SeatConfig(school="fire")])
    assert not any(plain._is_booster(s) for s in plain.seats)

    alone = LiveWorker(Telemetry(), "ice", [], "ttk-lookahead", 1,
                       booster_party=True)
    assert not alone._is_booster(alone.seats[0])


def test_the_hive_is_told_which_seats_are_boosters(qapp):
    """The overkill guard never holds a booster — its redundant hit is
    the party's insurance against the ledger's kill being a prediction
    — and the guard lives in the hivemind, so the hivemind has to know
    which seats those are."""
    from deimos_bridge.gui.live import LiveWorker, SeatConfig

    w = LiveWorker(Telemetry(), "ice", [], "ttk-lookahead", 1,
                   seats=[SeatConfig(school="fire"),
                          SeatConfig(school="storm")],
                   booster_party=True)
    hive = w._make_hive()
    assert hive is not None and hive.boosters == {1, 2}

    plain = LiveWorker(Telemetry(), "ice", [], "ttk-lookahead", 1,
                       seats=[SeatConfig(school="fire")])
    assert plain._make_hive().boosters == set()


def test_the_service_tick_gates_the_tracker_cures_off_boosters():
    """A booster's own quest tracker points wherever its book was left,
    so "curing" it pages the quest book, changes realms, and steals the
    wheel exactly when the quester's fight starts. The three cure rungs
    are gated off boosters in the tick itself, and the booster's own
    rung is the follow — never `_sync_follower`, because a booster is
    not levelling this questline."""
    import ast
    import inspect
    import textwrap

    from deimos_bridge.gui.live import LiveWorker

    src = textwrap.dedent(inspect.getsource(LiveWorker._service_loop))
    tree = ast.parse(src)
    guards = {}

    class Walk(ast.NodeVisitor):
        def visit_If(self, node):
            test = ast.unparse(node.test)
            for sub in node.body:
                for call in ast.walk(sub):
                    if (isinstance(call, ast.Call)
                            and getattr(call.func, "attr", "") == "_stage"
                            and len(call.args) >= 2
                            and isinstance(call.args[1], ast.Constant)):
                        guards.setdefault(call.args[1].value, []).append(
                            (test, ast.unparse(sub)))
            self.generic_visit(node)

    Walk().visit(tree)
    for label in ("re-arming the quest arrow",
                  "recovering the main questline", "changing realms"):
        assert any("_is_booster" in test for test, _b in guards[label]), \
            f"{label!r} runs for boosters"
    booster_rung = [b for test, b in guards["boosting the quester"]
                    if "_is_booster" in test]
    assert booster_rung, "no booster rung in the tick"
    assert all("_sync_follower" not in b for b in booster_rung)
    assert all("_follow_step" in b for b in booster_rung)


# ---- more than one boostee
#
# The operator's own question, in their words: "do we even have a mode
# for multiple boostees with a booster? I thought it was just the
# booster boostee at the moment". It was: `_is_booster` was "not the
# leader", so N seats gave one quester and N-1 boosters and nothing
# could spell anything else. Many boosters always worked; many QUESTERS
# did not exist.

def _boostee_worker(boosters=None, leader=0, seats=3):
    from deimos_bridge.gui.live import LiveWorker, SeatConfig

    return LiveWorker(Telemetry(), "ice", [], "ttk-lookahead", 1,
                      seats=[SeatConfig(school="fire")
                             for _ in range(seats - 1)],
                      booster_party=True, boosters=boosters, leader=leader)


def test_boosters_unset_still_means_every_non_leader(qapp):
    """The default has to be byte for byte what the mode always meant,
    because every run that exists was configured before roles did."""
    w = _boostee_worker(boosters=None, leader=1)
    assert w.boosters is None
    assert [w._is_booster(s) for s in w.seats] == [True, False, True]
    assert [w._is_boostee(s) for s in w.seats] == [False, False, False]
    assert [s.index for s in w._questers()] == [1]


def test_a_seat_left_out_of_the_boosters_is_a_second_quester(qapp):
    """Muscle is named now rather than inferred from "not the leader"."""
    w = _boostee_worker(boosters={2})
    assert [w._is_booster(s) for s in w.seats] == [False, False, True]
    assert [w._is_boostee(s) for s in w.seats] == [False, True, False]
    assert [s.index for s in w._questers()] == [0, 1]


def test_a_boostee_follows_nobody(qapp):
    """It is levelling its own questline, and a wizard walking to
    somebody else's marker cannot walk to its own."""
    w = _boostee_worker(boosters={2})
    assert [w._follows(s) for s in w.seats] == [False, False, True]


def test_a_booster_shadows_whichever_quester_is_fighting(qapp):
    """The operator's framing is the whole rule: "the booster needs to
    join combats to beat them as quick as possible"."""
    w = _boostee_worker(boosters={2})
    for seat in w.seats:
        seat.client = object()
    lead, boostee, muscle = w.seats
    # Nobody fighting: the leader, exactly as a one-quester party.
    assert w._boost_target(muscle) is lead
    boostee.in_duel, boostee.duel_since = True, 100.0
    assert w._boost_target(muscle) is boostee
    # ...and the longest-running fight first — that is the one help
    # shortens most, and ending it frees the booster for the other.
    lead.in_duel, lead.duel_since = True, 50.0
    assert w._boost_target(muscle) is lead
    lead.in_duel = False
    assert w._boost_target(muscle) is boostee


def test_a_quester_is_never_given_a_boost_target(qapp):
    w = _boostee_worker(boosters={2})
    for seat in w.seats:
        seat.client = object()
    w.seats[1].in_duel, w.seats[1].duel_since = True, 100.0
    assert w._boost_target(w.seats[0]) is w.seats[0]
    assert w._boost_target(w.seats[1]) is w.seats[0]


def test_the_duel_clock_stamps_the_transition_not_every_tick(qapp):
    """`_boost_target` asks which fight has been going longest, so the
    stamp has to be when the duel STARTED."""
    import inspect

    from deimos_bridge.gui.live import LiveWorker

    src = inspect.getsource(LiveWorker._service_loop)
    assert "seat.in_duel != was_fighting" in src, \
        "the duel clock is restamped every tick, so every fight is new"


def test_the_hive_is_not_told_a_boostee_is_muscle(qapp):
    """The overkill guard never holds a booster. A boostee is not one —
    it has a next fight of its own, which is the whole reason the guard
    exists."""
    w = _boostee_worker(boosters={2})
    assert w._make_hive().boosters == {2}


def test_the_tick_gives_a_boostee_its_own_quest_step():
    """A boostee gets the cure rungs a booster is gated off — it has a
    questline to lose — and its own quest step rather than a follow.
    It cannot reach the `auto_quest` arm below: that flag is
    worker-wide and "Booster party + script" leaves it off."""
    import ast
    import inspect
    import textwrap

    from deimos_bridge.gui.live import LiveWorker

    src = textwrap.dedent(inspect.getsource(LiveWorker._service_loop))
    tree = ast.parse(src)
    guards = {}

    class Walk(ast.NodeVisitor):
        def visit_If(self, node):
            test = ast.unparse(node.test)
            for sub in node.body:
                for call in ast.walk(sub):
                    if (isinstance(call, ast.Call)
                            and getattr(call.func, "attr", "") == "_stage"
                            and len(call.args) >= 2
                            and isinstance(call.args[1], ast.Constant)):
                        guards.setdefault(call.args[1].value, []).append(
                            (test, ast.unparse(sub)))
            self.generic_visit(node)

    Walk().visit(tree)
    for label in ("re-arming the quest arrow",
                  "recovering the main questline", "changing realms",
                  "walking through the door"):
        assert any("_is_boostee" in test for test, _b in guards[label]), \
            f"{label!r} is shut to a second quester"
    arms = [body for test, body in guards["questing on its own line"]
            if "_is_boostee" in test]
    assert arms, "no boostee rung in the tick"
    assert all("_quest_step" in body for body in arms)
    assert all("_follow_step" not in body for body in arms)
    # ...and the one case where its own line is the wrong line: while
    # the script cannot drive it at all, walking its own marker walks
    # it away from the party, and every quest is then done twice. See
    # `_sync_while_downgraded`.
    synced = [body for _t, body in guards["staying with the scripted wizard"]]
    assert synced, "a downgraded quester still walks off on its own"
    assert all("_sync_follower" in body for body in synced)


def test_only_the_boostee_shape_levels_more_than_one_questline(qapp):
    """The predicate the party rules stand down on, and it has to be
    narrow. `_questers()` is every seat outside booster mode, so a
    plain three-wizard party reads as three questers — guarding on THAT
    would take the majority-zone rule, the split-sigil drag and the
    regroup away from every party that has ever run."""
    from deimos_bridge.gui.live import LiveWorker, SeatConfig

    def party(**kw):
        return LiveWorker(Telemetry(), "ice", [], "ttk-lookahead", 1,
                          seats=[SeatConfig(school="fire"),
                                 SeatConfig(school="storm")], **kw)

    assert not party()._many_questlines()
    assert not party(follow_leader=True)._many_questlines()
    assert not party(booster_party=True)._many_questlines()
    assert party(booster_party=True, boosters={2})._many_questlines()


def test_a_second_quester_in_another_zone_is_not_a_straggler(monkeypatch):
    """There is no single "where the party is" when the party levels
    two questlines. The majority is only ever one of them — so with a
    quester, a booster and a second quester, the majority is whichever
    quester the booster is standing with, and the other would be
    dragged off its own step every poll."""
    worker, read_zone = _zoned_party(
        ["Olde Town", "Unicorn Way", "Olde Town"])
    worker.booster_party = True
    worker.leader = 0
    worker.boosters = {2}
    assert _look(worker, read_zone, monkeypatch) == (None, None)
    said = [e for e in worker.seats[1].tel.questing
            if e["kind"] == "rejoin-refused"]
    assert said, [e["kind"] for e in worker.seats[1].tel.questing]
    assert "questlines" in said[0]["detail"] \
        or "quester" in said[0]["detail"], said[0]["detail"]


def test_muscle_in_the_wrong_zone_is_still_a_straggler(monkeypatch):
    """A booster has no line of its own and its whole job is to be
    where a quester is. The refusal above is about questers only."""
    worker, read_zone = _zoned_party(
        ["Olde Town", "Olde Town", "Unicorn Way"])
    worker.booster_party = True
    worker.leader = 0
    worker.boosters = {2}
    assert _look(worker, read_zone, monkeypatch) == (None, None)
    worker.seats[2].stranded_since -= worker.STRANDED_AFTER + 1
    seat, _target = _look(worker, read_zone, monkeypatch)
    assert seat is worker.seats[2], "the booster was excused as a quester"


def test_the_export_names_a_boostee_and_counts_the_questlines(qapp):
    """Every party rule reads differently at two questlines, so an
    export that cannot say how many ran cannot be read at all."""
    w = _boostee_worker(boosters={2})
    assert [w._party_shape(s)["role"] for s in w.seats] == \
        ["leader", "boostee", "booster"]
    assert w._party_shape(w.seats[0])["questers"] == 2

    plain = _boostee_worker(boosters=None)
    assert [plain._party_shape(s)["role"] for s in plain.seats] == \
        ["leader", "booster", "booster"]
    assert plain._party_shape(plain.seats[0])["questers"] == 1


def test_the_export_names_the_wizards_the_script_actually_drives(
        monkeypatch):
    """Rev d91c3e24's export said `script_drives: "the leader only"` for
    a run whose VM held two clients and whose preset had answered
    "playercount 2 mode active". That field is what every other line in
    the file is read against, so it has to name what was BUILT."""
    worker, _built = _crewed_party(monkeypatch, boosters=(0,), leader=2)
    assert worker._party_shape(worker.seats[0])["script_drives"] == \
        "the leader only", "nothing is built yet"

    _build_the_script(worker)
    assert worker._party_shape(worker.seats[0])["script_drives"] == \
        "w1 and w2"

    # ...and a downgrade tells the truth about the one client it got.
    solo, _b = _crewed_party(monkeypatch, boosters=(0,), leader=2)
    solo.seats[1].wizard_name = ""
    _build_the_script(solo)
    assert solo._party_shape(solo.seats[0])["script_drives"] == "w2"


def test_the_questers_row_spells_todays_behaviour_when_untouched(qapp):
    """The row asks who QUESTS — the way somebody looks for it. Rev
    1f912030's operator wanted two questers, found a row labelled
    "Boosters", ticked all three and got one quester: "there was no
    option to select questers". Untouched it still means what booster
    mode has always meant, so a party nobody configured is unchanged."""
    from deimos_bridge.gui.app import MainWindow

    win = MainWindow(Telemetry())
    win.booster_party = True
    win.leader_pick.setCurrentIndex(0)
    win._sync_quester_row()
    assert win.booster_seats(3) is None, "an untouched row invented a role"
    win.quester_picks[1].setChecked(True)        # wizard 2 quests too
    assert win.booster_seats(3) == {2}, "ticking a quester made it muscle"
    # ...and outside booster mode the row means nothing at all.
    win.booster_party = False
    assert win.booster_seats(3) is None


def test_the_leaders_own_box_is_ticked_and_locked(qapp):
    """`_is_booster` refuses the leader outright, so a box that could be
    unticked would be a control that lies. It tracks the picker."""
