def test_a_changed_quest_name_is_read_twice_before_it_is_believed(
        monkeypatch):
    """The goal line got a second opinion because one read of an unnamed
    window slot could move the party. The NAME is what `questlist`
    places every wizard BY, and it had none.

    Rev 242ae08b: one read placed Thomas at Krokotopia #20 (`Permission
    to Enter`) while his own heartbeat said #6, and every `quest-desync`
    line in that 49-minute export reads "Thomas #20 (by quest name,
    clamped — it read #6, which is behind #20 it has already done)".
    The same run's `goal-flapped` fired nine times, four of them on a
    WIZARD CITY quest read off a wizard in Krokotopia."""
    import asyncio

    worker, seat = _goal_worker(
        monkeypatch, goals=["Talk To Professor Winthrop in Altar of Kings"],
        names=["Speak to the Assistant",     # believed: the first read
               "Permission to Enter",        # a changed name...
               "Speak to the Assistant"])    # ...its own second opinion
    asyncio.run(worker._read_goal(seat))
    assert seat.quest_name == "Speak to the Assistant"

    asyncio.run(worker._read_goal(seat))
    assert seat.quest_name == "Speak to the Assistant", \
        "one read of the tracked quest placed the wizard twelve quests on"
    flapped = [e for e in seat.tel.questing if e["kind"] == "name-flapped"]
    assert flapped and "Permission to Enter" in flapped[0]["detail"]


def test_a_quest_name_that_agrees_with_itself_is_believed(monkeypatch):
    """A real quest change reads the same twice from the next poll on,
    so it costs one `GOAL_CONFIRM` and nothing else."""
    import asyncio

    worker, seat = _goal_worker(
        monkeypatch, goals=["Talk To Professor Winthrop in Altar of Kings"],
        names=["Speak to the Assistant", "New Digs", "New Digs"])
    asyncio.run(worker._read_goal(seat))
    asyncio.run(worker._read_goal(seat))
    assert seat.quest_name == "New Digs", "a real quest change was refused"
    assert not [e for e in seat.tel.questing if e["kind"] == "name-flapped"]


def test_the_first_quest_name_a_seat_reads_is_taken_at_once(monkeypatch):
    """An unplaced wizard drops out of every comparison the questline
    makes, which is worse than a possibly-wrong one the next poll
    corrects. The same exception `_note_goal` has."""
    import asyncio

    worker, seat = _goal_worker(
        monkeypatch, goals=["Talk To Professor Winthrop in Altar of Kings"],
        names=["Speak to the Assistant"])
    assert seat.quest_name == ""
    asyncio.run(worker._read_goal(seat))
    assert seat.quest_name == "Speak to the Assistant"


def test_a_blank_quest_name_read_still_keeps_the_previous_one(monkeypatch):
    """Unchanged. A blank is not evidence the wizard changed quest —
    `maybe_text` returns "" for a zero length, a mid-write pointer or a
    decode failure — and it still expires at `NAME_MAX_AGE`."""
    import asyncio
    import time

    worker, seat = _goal_worker(
        monkeypatch, goals=["Talk To Professor Winthrop in Altar of Kings"],
        names=["Speak to the Assistant", ""])
    asyncio.run(worker._read_goal(seat))
    asyncio.run(worker._read_goal(seat))
    assert seat.quest_name == "Speak to the Assistant"
    assert not [e for e in seat.tel.questing if e["kind"] == "name-flapped"], \
        "a failed read was reported as a disagreement"

    seat.name_read_at = time.monotonic() - worker.NAME_MAX_AGE - 1
    asyncio.run(worker._read_goal(seat))
    assert seat.quest_name == "", "a dead read was kept as fact forever"


def _placed(worker, seat, world, order):
    """One placement through the clamp, as `_places` makes it."""
    from deimos_bridge import questlist

    return worker._no_further_back(
        seat, questlist.Position(world=world, order=order,
                                 name=f"#{order}", questline="main",
                                 how="by quest name"))


def test_a_questline_floor_that_is_always_contradicted_comes_down(qapp):
    """It took one placement to set a floor and nothing could ever lower
    it. Rev 242ae08b pinned Thomas at Krokotopia #20 against a steady #6
    for forty minutes; with the placement stuck, `_behind_basis` never
    said "questline", the catch-up gate that requires it never fired,
    and the other quester finished eight quests behind."""
    import time

    worker = _party_worker()
    seat = worker.seats[0]
    assert _placed(worker, seat, "Krokotopia", 20).order == 20
    got = _placed(worker, seat, "Krokotopia", 6)
    assert got.order == 20 and "clamped" in got.how, \
        "the clamp stopped clamping"

    # ...and the same reading, held past the deadline.
    doubted, _since = seat.floor_doubted["Krokotopia"]
    seat.floor_doubted["Krokotopia"] = (
        doubted, time.monotonic() - worker.FLOOR_WRONG_AFTER - 1)
    got = _placed(worker, seat, "Krokotopia", 6)
    assert got.order == 6, "a floor that was never true stood forever"
    assert "clamped" not in (got.how or "")
    said = [e for e in seat.tel.questing
            if e["kind"] == "questline-floor-lowered"]
    assert said and "#20" in said[0]["detail"] and "#6" in said[0]["detail"]
    # And it stays down.
    assert _placed(worker, seat, "Krokotopia", 6).order == 6


def test_a_briefly_contradicted_floor_still_clamps(qapp):
    """The control, and the case the clamp was written for. Rev
    3822cc6c's Sebastian read Krokotopia #7 for ONE tick — a real goal
    belonging to #7 — and was back at #15 fifteen seconds later. The
    party declared an eight-quest gap and paused the script for it."""
    worker = _party_worker()
    seat = worker.seats[0]
    _placed(worker, seat, "Krokotopia", 15)
    got = _placed(worker, seat, "Krokotopia", 7)
    assert got.order == 15 and "clamped" in got.how
    # Fifteen seconds later it reads #15 again, and the doubt is gone.
    assert _placed(worker, seat, "Krokotopia", 15).order == 15
    assert "Krokotopia" not in seat.floor_doubted
    assert not [e for e in seat.tel.questing
                if e["kind"] == "questline-floor-lowered"]


def test_a_seat_that_holds_a_different_wizard_loses_the_old_ones_floor(
        qapp):
    """The floor is exactly as per-wizard as the round record it sits
    beside, and nothing cleared it — so a seat that came back holding a
    different client kept the last wizard's progress as a floor the new
    one could not read below. "The clients come back in whatever order
    the game was launched in"."""
    from types import SimpleNamespace

    worker = _party_worker()
    seat = worker.seats[0]
    _placed(worker, seat, "Krokotopia", 40)
    seat.tel.wizard = "Konstantin"
    seat.wizard_name = None

    worker._learn_name(seat, SimpleNamespace(
        state=SimpleNamespace(player=SimpleNamespace(name="Thomas"))))
    assert seat.tel.wizard == "Thomas"
    assert seat.furthest == {}, "the new wizard inherited a floor"
    assert _placed(worker, seat, "Krokotopia", 2).order == 2


def test_a_marker_cannot_be_out_of_zone_when_the_goal_names_this_zone(
        monkeypatch):
    """`MARKER_IN_ZONE` assumes another zone comes back as six figures;
    run backwards that says six figures means another zone, and rev
    242ae08b shows the second half failing on its own. Thomas read
    98,673 / 99,824 / 98,813 / 97,435 for `Talk To Professor Winthrop in
    Altar of Kings` while standing IN `KT_Pyramid/KT_AltarOfKings`."""
    import asyncio

    worker, seat = _goal_worker(
        monkeypatch, goals=["Talk To Professor Winthrop in Altar of Kings"],
        positions=[_XYZ(5000.0, 0.0, 0.0), _XYZ(98673.0, 0.0, 0.0)])
    seat.zone_seen = "Krokotopia/KT_Pyramid/KT_AltarOfKings"
    asyncio.run(worker._read_goal(seat))
    assert seat.marker_away == 5000.0

    asyncio.run(worker._read_goal(seat))
    assert seat.marker_away == 5000.0, \
        "the objective is in the room the wizard is standing in"
    said = [e for e in seat.tel.questing if e["kind"] == "marker-impossible"]
    assert said and "98,673" in said[0]["detail"]
    assert worker._marker_out_of_reach([seat]) is None


def test_a_far_marker_with_no_zone_change_is_not_another_zone(monkeypatch):
    """The preset opens every main-loop iteration with

        print "Teleporting all clients to a safe area."
        times 2 { tp XYZ(0,100000,0) }

    -- `questing.NOWHERE` -- so a wizard standing at its quest NPC is
    yanked 100,000 units up and sampled there. Rev b37ab0a2 did that
    152 times: Thomas's marker read 1,616 and then 75,742 in the SAME
    room, seven times over, and wizAi restarted the script six times
    saying "another zone ... No teleport can help from here" about an
    NPC ten feet away. 79 of that run's 136 minutes went on the one
    conversation.

    `area_is_this_zone('Grand Arena',
    'Krokotopia/KT_Krokosphinx/KT_Arena')` answers None, so Phase AG
    cannot reach this. The wizard's own reading a minute ago can."""
    import asyncio

    worker, seat = _goal_worker(
        monkeypatch, goals=["Talk To Arena Master in Grand Arena"],
        positions=[
            _XYZ(1616.0, 0.0, 0.0),                          # at the NPC
            _XYZ(75742.0, 0.0, 0.0), _XYZ(75742.0, 0.0, 0.0),  # parked
            _XYZ(3470.0, 0.0, 0.0), _XYZ(3470.0, 0.0, 0.0),    # back — 1
            _XYZ(75742.0, 0.0, 0.0), _XYZ(75742.0, 0.0, 0.0),  # parked
            _XYZ(541.0, 0.0, 0.0), _XYZ(541.0, 0.0, 0.0),      # back — 2
            _XYZ(75742.0, 0.0, 0.0),                           # and again
        ])
    seat.zone_seen = "Krokotopia/KT_Krokosphinx/KT_Arena"
    worker.MARKER_FLAP_REST = 0.0

    asyncio.run(worker._read_goal(seat))
    assert seat.marker_away == 1616.0
    assert seat.marker_near[:2] == (seat.zone_seen, seat.goal)

    # Two believed round trips: the marker keeps coming back to this
    # zone on this goal, which nothing in another zone does.
    for _ in range(5):
        asyncio.run(worker._read_goal(seat))
    assert seat.marker_bounces >= worker.MARKER_BOUNCES, seat.marker_bounces

    asyncio.run(worker._read_goal(seat))
    assert seat.marker_away == worker.MARKER_IN_ZONE, \
        "the wizard moved; the objective did not"
    assert worker._marker_out_of_reach([seat]) is None
    said = [e for e in seat.tel.questing if e["kind"] == "marker-same-zone"]
    assert said and "75,742" in said[0]["detail"]


def test_the_same_far_marker_after_a_zone_change_is_believed(monkeypatch):
    """The control, and the whole precondition: another zone needs a
    ZONE CHANGE. A wizard that crossed one has no receipt to show."""
    import asyncio

    worker, seat = _goal_worker(
        monkeypatch, goals=["Talk To Arena Master in Grand Arena"],
        positions=[
            _XYZ(1616.0, 0.0, 0.0),
            _XYZ(75742.0, 0.0, 0.0), _XYZ(75742.0, 0.0, 0.0),
            _XYZ(3470.0, 0.0, 0.0), _XYZ(3470.0, 0.0, 0.0),
            _XYZ(75742.0, 0.0, 0.0), _XYZ(75742.0, 0.0, 0.0),
            _XYZ(541.0, 0.0, 0.0), _XYZ(541.0, 0.0, 0.0),
            _XYZ(75742.0, 0.0, 0.0),
        ])
    seat.zone_seen = "Krokotopia/KT_Krokosphinx/KT_Arena"
    worker.MARKER_FLAP_REST = 0.0
    # Everything the vouch needs EXCEPT the standing-still part.
    for _ in range(6):
        asyncio.run(worker._read_goal(seat))
    assert seat.marker_bounces >= worker.MARKER_BOUNCES

    seat.zone_seen = "Krokotopia/KT_Hub"
    asyncio.run(worker._read_goal(seat))
    assert seat.marker_away == 75742.0
    assert worker._marker_out_of_reach([seat]) == 75742.0


def test_the_same_far_marker_after_the_goal_moved_is_believed(monkeypatch):
    """The other half of the precondition, and the reason the receipt
    carries the goal as well as the zone: a quest that advanced to
    another world without the wizard moving is exactly
    `goal_is_elsewhere`'s case, and vouching for it on the zone alone
    would re-create the bug rev 09a0af80 paid for at 81 units."""
    import asyncio

    worker, seat = _goal_worker(
        monkeypatch,
        goals=["Talk To Arena Master in Grand Arena"] * 7
              + ["Talk To Merle Ambrose in The Commons"],
        positions=[
            _XYZ(1616.0, 0.0, 0.0),
            _XYZ(75742.0, 0.0, 0.0), _XYZ(75742.0, 0.0, 0.0),
            _XYZ(3470.0, 0.0, 0.0), _XYZ(3470.0, 0.0, 0.0),
            _XYZ(75742.0, 0.0, 0.0), _XYZ(75742.0, 0.0, 0.0),
            _XYZ(541.0, 0.0, 0.0), _XYZ(541.0, 0.0, 0.0),
            _XYZ(75742.0, 0.0, 0.0),
        ])
    seat.zone_seen = "Krokotopia/KT_Krokosphinx/KT_Arena"
    worker.MARKER_FLAP_REST = 0.0
    for _ in range(6):
        asyncio.run(worker._read_goal(seat))
    assert seat.marker_bounces >= worker.MARKER_BOUNCES

    # The step advanced without the wizard moving — which is exactly
    # `goal_is_elsewhere`'s case, and it read 81 units at rev 09a0af80.
    asyncio.run(worker._read_goal(seat))
    assert seat.goal == "Talk To Merle Ambrose in The Commons", \
        "the fixture's goal never moved"
    assert seat.marker_away == 75742.0


def test_a_clamped_reading_does_not_renew_its_own_vouch(monkeypatch):
    """Phase AK's lesson, applied one rung over. A fallback that writes
    the receipt it was authorised by keeps itself alive forever — rev
    e86044f2 held one impossible distance "480 times in a row" doing
    exactly that. Only the RAW reading may vouch."""
    import asyncio

    worker, seat = _goal_worker(
        monkeypatch, goals=["Talk To Arena Master in Grand Arena"],
        positions=[
            _XYZ(1616.0, 0.0, 0.0),
            _XYZ(75742.0, 0.0, 0.0), _XYZ(75742.0, 0.0, 0.0),
            _XYZ(3470.0, 0.0, 0.0), _XYZ(3470.0, 0.0, 0.0),
            _XYZ(75742.0, 0.0, 0.0), _XYZ(75742.0, 0.0, 0.0),
            _XYZ(541.0, 0.0, 0.0), _XYZ(541.0, 0.0, 0.0),
            _XYZ(75742.0, 0.0, 0.0),
        ])
    seat.zone_seen = "Krokotopia/KT_Krokosphinx/KT_Arena"
    worker.MARKER_FLAP_REST = 0.0
    for _ in range(6):
        asyncio.run(worker._read_goal(seat))
    first, bounces = seat.marker_near, seat.marker_bounces
    assert bounces >= worker.MARKER_BOUNCES, bounces

    asyncio.run(worker._read_goal(seat))
    assert seat.marker_away == worker.MARKER_IN_ZONE
    assert (seat.marker_near, seat.marker_bounces) == (first, bounces), \
        "the clamp refreshed the receipt that authorised it"


def test_a_far_marker_is_still_believed_when_the_area_does_not_match(
        monkeypatch):
    """The control. `area_is_this_zone` documents itself as a veto that
    "may never authorise", so `False` and `None` change nothing — an
    interior, a hub under an internal alias and a wizard walking towards
    its area all answer `None`, and their markers may genuinely be out
    of zone."""
    import asyncio

    worker, seat = _goal_worker(
        monkeypatch, goals=["Find Key Stone Pile of Dirt in Royal Hall"],
        positions=[_XYZ(5000.0, 0.0, 0.0), _XYZ(96727.0, 0.0, 0.0),
                   _XYZ(96727.0, 0.0, 0.0)])
    seat.zone_seen = "Krokotopia/KT_Pyramid/KT_AltarOfKings"
    assert not worker._marker_cannot_be_out_of_zone(seat)
    asyncio.run(worker._read_goal(seat))
    asyncio.run(worker._read_goal(seat))
    assert seat.marker_away == 96727.0
    assert not [e for e in seat.tel.questing
                if e["kind"] == "marker-impossible"]


# ---------------------------------------------------------------------
# Run 14 (rev e86044f2): a correct quest name thrown away, and eight
# catch-ups for a 43-quest gap that was never there.
# ---------------------------------------------------------------------


def test_a_disowned_name_is_kept_when_the_goal_offers_somewhere_far(qapp):
    """Thomas's tracked quest was `Fangdango` — Krokotopia main #21,
    correct, on-main, comparable. Its goal line `Talk To Alhazred in
    Balance School` is simply missing from that quest's recorded
    objectives while `Back to Balance` (#56) does list it, so
    `goal_disowns` called the name stale and the goal fallback placed
    him THIRTY-FIVE quests on. The party read as 43 apart and eight
    catch-ups paused the script over it.

    A stale name lags by a quest or two. That is `goal_disowns`'s own
    premise, and nothing bounded what it handed over to."""
    from deimos_bridge import questlist

    worker = _party_worker()
    seat = worker.seats[0]
    seat.quest_name = "Fangdango"
    seat.goal = "Talk To Alhazred in Balance School"
    # The premise: the index really does disown it, and really does
    # place the goal line thirty-five quests further on.
    assert questlist.goal_disowns(seat.quest_name, seat.goal)
    assert questlist.position_from_goal(
        seat.goal, "Krokotopia", None).order == 56

    place = worker._place_by_name(seat)
    assert place.order == 21, "a correct on-main name was thrown away"
    said = [e for e in seat.tel.questing if e["kind"] == "name-kept-over-goal"]
    assert said and "#56" in said[0]["detail"] and "#21" in said[0]["detail"]


def test_a_name_the_goal_disowns_by_a_step_or_two_still_places_nothing(qapp):
    """The control, and the case `goal_disowns` was written for. Rev
    30e83468: `_read_goal` keeps the previous quest name on a blank
    read, so the name lags the goal by a quest — and a stale name that
    still places beat a fresh goal that was never consulted, holding
    Sebastian two quests behind Konstantin."""
    from deimos_bridge import questlist

    worker = _party_worker()
    seat = worker.seats[0]
    # Krokotopia #18 against #20 — inside DISOWN_SPAN either way.
    seat.quest_name = questlist.quest_at("Krokotopia", 18).name
    seat.goal = "Talk To Sergeant Major Talbot in The Oasis"
    if not questlist.goal_disowns(seat.quest_name, seat.goal):
        import pytest
        pytest.skip("the index no longer disowns this pair")
    near = questlist.position_from_goal(seat.goal, "Krokotopia", None)
    if near.comparable and abs(near.order - 18) > worker.DISOWN_SPAN:
        import pytest
        pytest.skip("this pair is no longer a short lag")
    assert not worker._place_by_name(seat).comparable, \
        "a genuinely stale name was placed anyway"


def test_a_name_the_index_cannot_place_still_falls_through(qapp):
    """Untouched. `DISOWN_SPAN` is about a name that DOES place; a name
    the book has never heard of has nothing to compare against and the
    goal fallback is the only answer there is."""
    worker = _party_worker()
    seat = worker.seats[0]
    seat.quest_name = "You Can Dig It"
    seat.goal = "Talk To Alhazred in Balance School"
    assert not worker._place_by_name(seat).comparable


def _goal_text_party():
    """Two questers, the ahead one placed by its GOAL rather than a name.

    Exactly rev e86044f2's shape: `placed: wizard 1 #56 (by goal text) ·
    wizard 2 #12 (by quest name)`.
    """
    worker = _two_quester_party(orders=(18, 23), booster_order=0)
    lead, other, _muscle = worker.seats
    # Both in Krokotopia, or `furthest_behind` refuses the comparison
    # for a different reason (a party split across worlds is not a gap
    # in one line) and this would prove nothing.
    lead.quest_name = "Gather the Troops"          # Krokotopia #12
    lead.goal = "Talk To Private Livingston in Palace of Fire"
    lead.goals_seen = [lead.goal]
    # ...and the wizard the run read at Krokotopia #56 off one shared
    # goal line, with no quest name of its own to place by.
    other.quest_name = ""
    other.goal = "Talk To Alhazred in Balance School"
    other.goals_seen = [other.goal]
    return worker


def test_a_gap_measured_off_a_goal_line_does_not_pause_the_script(qapp):
    """`read_quest_name` exists because the goal fallback is weak in
    exactly this direction: "one goal line belongs to as many as nine
    quests seventeen steps apart -- and `_catch_up` MOVES wizards".
    Rev e86044f2 measured 43 quests off one such placement.

    Phase AL turned the ban into a bound and this is the half of it
    that still refuses: 44 quests is not a wizard that missed a
    turn-in, and a catch-up drives one step at a time."""
    import time

    worker = _goal_text_party()
    assert worker._placed_by_goal_text(), "the fixture places by name"

    worker._check_in_step(worker.seats[0])
    worker._in_step_since = time.monotonic() - 600
    worker._check_in_step(worker.seats[0])

    assert worker._behind_gap > worker.GOAL_TEXT_GAP, \
        "the fixture's gap is no longer past the bound"
    assert worker._catching_up() == [], \
        "the script was paused on a goal-line measurement"
    said = [e for e in worker.seats[0].tel.questing
            if e["kind"] == "catch-up-refused-goal-text"]
    assert said and "goal line" in said[0]["detail"]
    # ...and the desync is still REPORTED. The gap is worth knowing.
    assert [e for e in worker.seats[0].tel.questing
            if e["kind"] == "quest-desync"]


def test_a_gap_measured_off_quest_names_still_starts_a_catch_up(qapp):
    """The control. Nothing about a name-based measurement changes."""
